CREATE TABLE `pickleball_seasons` (
  `id` int NOT NULL,
  `name` varchar(100) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `is_active` tinyint NOT NULL DEFAULT '0',
  `ladder_type` enum('singles','doubles','mixed') NOT NULL DEFAULT 'singles',
  `max_players` int DEFAULT '50',
  `challenge_window_days` int DEFAULT '7',
  `min_games_per_week` int DEFAULT '1'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Dumping data for table `pickleball_seasons`
--

INSERT INTO `pickleball_seasons` (`id`, `name`, `start_date`, `end_date`, `is_active`, `ladder_type`, `max_players`, `challenge_window_days`, `min_games_per_week`) VALUES
(1, '2025 Fall Pickleball Ladder', '2025-10-04', '2025-11-22', 1, 'doubles', 15, 7, 1);

